theme.css:
/* theme: Tariff Tension | A trade war on the horizon, markets catching their breath, and a world bracing for retaliation — logged in amber ink on a dark, watchful page. */
/* mood: tense */
/* layout: hero=centered; major-events=banner/grid-2; political-news=numbered/stack; financial-news=stat/stack; tech-news=outline/grid-2; entertainment-news=plain/stack; sports=split/masonry; music-releases=plain/stack; stock-analysis=stat/grid-3; outlook=tile/grid-2 */

.diary-page {
  --paper: #1d1607;
  --paper-alt: #2a2110;
  --ink: #f4e8c9;
  --ink-soft: #d9c9a3;
  --muted: #b8a67c;
  --accent: #ffad33;
  --accent-ink: #1d1607;
  --rule: #4a3d1f;
  --font-display: var(--ff-syne), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), system-ui, sans-serif;
}

.diary-page .diary-hero {
  background: var(--paper-alt);
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-hero-inner {
  padding-block: 3rem 3.5rem;
}

.diary-page .diary-kicker {
  color: var(--accent);
  letter-spacing: 0.3em;
  font-size: 0.7rem;
}

.diary-page .diary-title {
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.05;
  text-transform: uppercase;
  max-width: 24ch;
  margin-inline: auto;
}

.diary-page .diary-summary {
  font-size: clamp(1.05rem, 1.8vw, 1.25rem);
  line-height: 1.65;
  max-width: 36rem;
  margin-inline: auto;
}

.diary-page .diary-theme-note {
  font-size: 0.8rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  max-width: 36rem;
  margin-inline: auto;
}

.diary-page .diary-theme-name {
  background: var(--accent);
  color: var(--accent-ink);
  border-radius: 2px;
  padding: 0.15rem 0.7rem;
  letter-spacing: 0.12em;
}

.diary-page .diary-toc {
  background: var(--paper);
  border-bottom: 1px solid var(--rule);
}

.diary-page .diary-toc-label {
  color: var(--accent);
  letter-spacing: 0.2em;
}

.diary-page .diary-toc-link {
  color: var(--muted);
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-link.is-active {
  color: var(--ink);
}

.diary-page .diary-toc-number {
  color: var(--accent);
}

.diary-page .diary-section {
  border-top: 1px solid var(--rule);
}

.diary-page .diary-section-head {
  border-bottom: 2px solid var(--accent);
  padding-bottom: 0.75rem;
  margin-bottom: 2rem;
}

.diary-page .diary-section-number {
  color: var(--accent);
  font-size: 0.9rem;
  font-weight: 700;
  letter-spacing: 0.15em;
}

.diary-page .diary-section-title {
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-size: clamp(1.7rem, 3vw, 2.3rem);
}

.diary-page .diary-prose {
  font-size: 1.08rem;
  line-height: 1.75;
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom: 1px solid var(--accent);
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
  border-bottom-color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--accent);
}

.diary-page .diary-card-title {
  font-weight: 800;
  letter-spacing: -0.01em;
  line-height: 1.15;
}

.diary-page .diary-card-thread {
  border-color: var(--accent);
  color: var(--accent);
}

.diary-page .diary-card-thread:hover {
  background: var(--accent);
  color: var(--accent-ink);
}

.diary-page .diary-card--banner .diary-card-inner {
  border: 1px solid var(--rule);
  border-radius: 4px;
  overflow: hidden;
}

.diary-page .diary-card--banner .diary-card-title {
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 1.1rem;
  letter-spacing: 0.03em;
  padding: 0.9rem 1.25rem;
}

.diary-page .diary-card--banner .diary-card-body {
  padding: 1.25rem;
  background: var(--paper-alt);
}

.diary-page .diary-card--numbered .diary-card-inner {
  border-left: 3px solid var(--accent);
  padding-left: 1.5rem;
}

.diary-page .diary-card--numbered .diary-card-index {
  font-size: 2.75rem;
  font-weight: 800;
  color: var(--accent);
  opacity: 0.85;
}

.diary-page .diary-card--stat .diary-card-inner {
  border-top: 3px solid var(--accent);
  background: var(--paper-alt);
  padding: 1.25rem;
  border-radius: 4px;
}

.diary-page .diary-card-figure {
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--accent);
}

.diary-page .diary-card--outline .diary-card-inner {
  border: 1px solid var(--rule);
  border-radius: 4px;
  background: var(--paper);
  box-shadow: 0 4px 12px -6px rgb(0 0 0 / 0.6);
}

.diary-page .diary-card--split .diary-card-inner {
  border-top: 3px solid var(--accent);
}

.diary-page .diary-card--tile .diary-card-inner {
  background: var(--paper-alt);
  border-radius: 4px;
  border: 1px solid var(--rule);
}

.diary-page .diary-card--timeline .diary-card-inner::before {
  background: var(--rule);
}

.diary-page .diary-card--timeline .diary-card-inner::after {
  background: var(--accent);
  box-shadow: 0 0 0 4px var(--paper);
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
}

.diary-page .diary-spark.is-up {
  color: var(--ink);
}

.diary-page .diary-spark.is-down {
  color: var(--accent);
}

.diary-page .diary-spark .diary-spark-value {
  color: var(--ink);
}

.diary-page .diary-spark .diary-spark-change {
  color: var(--accent);
}

.diary-page .diary-spark.is-up .diary-spark-change {
  color: var(--accent);
}

.diary-page .diary-footer {
  border-top: 1px solid var(--rule);
}

.diary-page .diary-footer a {
  color: var(--accent);
}

.diary-page .diary-footer a:hover {
  color: var(--ink);
}

@media (min-width: 1024px) {
  .diary-page .diary-toc {
    border-left: 1px solid var(--rule);
  }

  .diary-page .diary-toc-list {
    border-left-color: var(--rule);
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: var(--accent);
  }
}

@media (prefers-reduced-motion: reduce) {
  .diary-page *,
  .diary-page *::before,
  .diary-page *::after {
    animation: none !important;
    transition: none !important;
  }
}
